package com.smritisathi.app.memory;
import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import com.google.gson.*;import com.smritisathi.app.core.*;import java.net.*;
public class MemoryMomentsActivity extends BaseActivity {LinearLayout list;@Override public void onCreate(Bundle b){super.onCreate(b);root.setBackgroundColor(Color.BLACK);header("Family Memory Moments");list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);load();}void load(){ApiClient.request("GET","/moments/patient/"+Session.id(this),Session.token(this),null,(ok,d,e)->{list.removeAllViews();if(ok&&d.has("data")&&d.getAsJsonArray("data").size()>0)for(JsonElement x:d.getAsJsonArray("data"))addMoment(x.getAsJsonObject());else{UI.toast(this,"No memory moments yet");addMoment(ApiClient.obj("caption","Family memories will appear here.","personName","Loved Ones","relationship","Family"));}});}void addMoment(JsonObject m){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(16,16,16,16);card.setBackgroundColor(Color.rgb(25,25,25));ImageView im=new ImageView(this);im.setLayoutParams(new LinearLayout.LayoutParams(-1,420));im.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(im);TextView who=UI.text(this,(m.has("personName")?m.get("personName").getAsString():"Loved One")+" — "+(m.has("relationship")?m.get("relationship").getAsString():"Family Member"));who.setTextColor(Color.WHITE);card.addView(who);Button more=UI.button(this,"📖 Tell me more");card.addView(more);TextView desc=UI.text(this,m.has("caption")?m.get("caption").getAsString():"");desc.setTextColor(Color.WHITE);desc.setVisibility(View.GONE);card.addView(desc);more.setOnClickListener(v->{desc.setVisibility(desc.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);});list.addView(card);if(m.has("imageUrl")){String u=m.get("imageUrl").getAsString();new Thread(()->{try{Bitmap bm=BitmapFactory.decodeStream(new URL(u).openStream());new Handler(Looper.getMainLooper()).post(()->im.setImageBitmap(bm));}catch(Exception ignored){}}).start();}}}
